export function wordPicture(word){if(!drawings[word])throw Error('Missing picture: '+word);return `<svg viewBox="0 0 130 130" role="img" aria-label="${word}" xmlns="http://www.w3.org/2000/svg"><g fill="#284c48">${drawings[word]}</g></svg>`;}
export function hasPicture(word){return !!drawings[word];}
export function rescueScene(stage=0){const steps=Math.max(0,Math.min(3,stage)),liftY=178-steps*29;return `<svg class="rescue-scene" viewBox="0 0 310 260" role="img" aria-label="${steps===3?'Robot rescued':steps+' of 3 rescue systems powered'}"><rect width="310" height="260" rx="20" fill="#dcebd9"/><circle cx="225" cy="42" r="28" fill="#f5df92"/><path d="M0 216V124h53v92m5 0V153h33v63m142 0V102h29v114m8 0V133h43v83" fill="#a9c5ad"/><rect x="198" y="67" width="16" height="160" rx="5" fill="#6e9581"/><rect x="204" y="83" width="7" height="133" rx="3" fill="#bfd7b9"/><g class="rescue-lift" style="transform:translateY(${liftY}px)"><rect x="71" y="7" width="140" height="13" rx="5" fill="#24675d"/><path d="M85 7v-27m100 27v-27" stroke="#24675d" stroke-width="5"/><g transform="translate(104 -73) scale(.48)">${robot().replace(/<svg[^>]*>|<\/svg>/g,'')}</g></g><rect x="206" y="76" width="84" height="14" rx="5" fill="#426e61"/><rect x="220" y="31" width="59" height="45" rx="7" fill="${steps===3?'#f3cb64':'#d9e0cb'}"/><path d="m237 57 8 8 16-18" fill="none" stroke="${steps===3?'#166d5d':'#9ab298'}" stroke-width="5"/><path d="M0 231h310" stroke="#6e9581" stroke-width="8"/><g>${[0,1,2].map((x)=>`<rect x="${40+x*65}" y="232" width="42" height="19" rx="5" fill="${steps>x?'#f2cb63':'#90ad97'}"/><circle cx="${61+x*65}" cy="241" r="5" fill="${steps>x?'#fff4c8':'#628a72'}"/>`).join('')}</g>${steps===3?'<g fill="#dd8f42"><path d="m57 39 3 8 9 3-9 3-3 9-3-9-8-3 8-3z"/><path d="m140 30 3 8 9 3-9 3-3 9-3-9-8-3 8-3z"/></g>':''}</svg>`;}
